sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 from;
uniform float2 to;
uniform float width;
uniform float jag;
uniform float evolution;
uniform float glow;
layout(color) uniform half4 color;
uniform float seed;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
float fbm(float3 p, float octaves, float2 drift, float gain) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 9; i++) {
        if (float(i) >= octaves) break;
        sum += amp * vnoise(p);
        norm += amp;
        amp *= gain;
        p = float3(p.xy * 2.03 + drift + float2(17.13, 9.71), p.z * 1.7 + 3.1);
    }
    return sum / max(norm, 0.0001);
}
float bolt(float2 coord, float2 a, float2 b, float amp, float salt) {
    float2 ab = b - a;
    float len = max(length(ab), 1.0);
    float2 dir = ab / len;
    float2 nrm = float2(-dir.y, dir.x);
    float t = clamp(dot(coord - a, dir) / len, 0.0, 1.0);
    float n = fbm(float3(t * 6.0 + salt, seed * 3.1 + salt, evolution), 6.0, float2(0.0), 0.62) - 0.5;
    float2 at = a + ab * t + nrm * n * amp * len * sin(3.1415927 * t);
    return length(coord - at);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 a = from * size;
    float2 b = to * size;
    float d = bolt(coord, a, b, jag * 2.0, 0.0);
    float2 mid = mix(a, b, 0.45) + float2(-(b - a).y, (b - a).x) * (fbm(float3(seed, 7.7, evolution), 3.0, float2(0.0), 0.5) - 0.5) * jag;
    float2 fork = mid + (b - a) * 0.35 + float2(-(b - a).y, (b - a).x) * 0.25 * jag * 2.0;
    d = min(d, bolt(coord, mid, fork, jag * 2.0, 17.3) + width * 0.4);
    float core = 1.0 - smoothstep(width * 0.25, width * 0.5 + 0.5, d);
    float halo = exp(-d / max(width * 3.0, 0.5)) * glow;
    float3 base = float3(src.rgb) / float(src.a);
    float3 light = float3(color.rgb) * halo + float3(core);
    float3 rgb = clamp(base + light - base * light, 0.0, 1.0);
    return half4(half3(rgb) * src.a, src.a);
}
